import { useEffect, useMemo, useState } from "react";
import {
  analyzeApplication, analyzeDocument, createApplication, deleteDocument,
  extractDocument, getApplication, getApplicationAnalysis, getApplications,
  getDocumentAnalysis, getDocuments, getDocumentText, updateApplication,
  updateDocumentCategory, updateStatus, uploadDocument, getValidation,
  recalculateValidation, validateApplication,
  analyzeApplicationPolicy, deletePolicy, getPolicies, searchPolicies, uploadPolicy,
  getUnderwritingEvents, getUnderwritingReport, runUnderwriting,
  login, register, getMe, logout, intakeApplication,
} from "./api";

const statuses = ["Draft", "Processing", "Needs Review", "Completed"];
const categories = ["Salary Slip", "Bank Statement", "Income Tax Return", "Identity Proof", "Property Document", "Other"];
const emptyForm = { borrower_name: "", email: "", phone: "", monthly_income: "", monthly_debt: "", loan_amount: "", property_value: "", property_address: "", employment_type: "" };

function formatMoney(value) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(value || 0); }
function formatDate(value) { return new Date(value).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); }
function formatSize(bytes) { return bytes < 1024 * 1024 ? `${Math.ceil(bytes / 1024)} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB`; }
function StatusBadge({ status }) {
  const styles = { Draft: "bg-slate-100 text-slate-600", Processing: "bg-blue-50 text-blue-700", "Needs Review": "bg-amber-50 text-amber-700", Completed: "bg-emerald-50 text-emerald-700", Uploaded: "bg-slate-100 text-slate-600", Extracted: "bg-emerald-50 text-emerald-700", Failed: "bg-red-50 text-red-700", Pending: "bg-slate-100 text-slate-600", Valid: "bg-emerald-50 text-emerald-700", "Missing Information": "bg-amber-50 text-amber-700", "Policy Review Required": "bg-orange-50 text-orange-700", "Verified Match": "bg-emerald-50 text-emerald-700", "Minor Difference": "bg-amber-50 text-amber-700", "Unable to Compare": "bg-slate-100 text-slate-600" };
  return <span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${styles[status] || "bg-slate-100 text-slate-600"}`}>{status}</span>;
}
function Loading() { return <div className="flex items-center justify-center py-12 text-sm text-slate-500"><span className="mr-2 h-4 w-4 animate-spin rounded-full border-2 border-blue-200 border-t-blue-600" />Loading...</div>; }
function Login({ onLogin }) {
  const [mode, setMode] = useState("login"); const [fullName, setFullName] = useState(""); const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  const isRegistering = mode === "register";
  const submit = async (event) => {
    event.preventDefault();
    try {
      setBusy(true); setError("");
      const response = isRegistering
        ? await register({ full_name: fullName, email, password })
        : await login({ email, password });
      localStorage.setItem("mortgage_access_token", response.data.access_token);
      onLogin(response.data.user);
    } catch (err) {
      const detail = err.response?.data?.detail;
      const message = Array.isArray(detail)
        ? detail.map((item) => item.msg).join(" ")
        : detail;
      setError(message || (err.request
        ? "Could not connect to the backend. Make sure it is running at http://localhost:8000."
        : (err.message || (isRegistering ? "Could not create the account." : "Login failed."))));
    } finally { setBusy(false); }
  };
  const switchMode = () => { setMode(isRegistering ? "login" : "register"); setError(""); };
  return <div className="grid min-h-screen place-items-center bg-slate-50 p-5"><form onSubmit={submit} className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-8 shadow-sm"><div className="mb-8 text-center"><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-xl bg-blue-600 font-bold text-white">M</div><h1 className="text-2xl font-bold text-slate-900">Mortgage</h1><p className="mt-1 text-sm text-slate-500">Secure loan processing workspace</p></div>{error && <div className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</div>}{isRegistering && <label className="text-sm font-semibold">Full name<input className="field" type="text" required value={fullName} onChange={(e) => setFullName(e.target.value)} /></label>}<label className="text-sm font-semibold">Email<input className="field" type="email" required value={email} onChange={(e) => setEmail(e.target.value)} /></label><label className="text-sm font-semibold">Password<input className="field" type="password" minLength={8} required value={password} onChange={(e) => setPassword(e.target.value)} /></label><button className="primary-button mt-3 w-full" disabled={busy}>{busy ? (isRegistering ? "Creating account..." : "Signing in...") : (isRegistering ? "Sign up" : "Sign in")}</button><p className="mt-5 text-center text-sm text-slate-500">{isRegistering ? "Already have an account?" : "Don't have an account?"}{" "}<button type="button" onClick={switchMode} className="font-semibold text-blue-600 hover:text-blue-800">{isRegistering ? "Sign in" : "Sign up"}</button></p></form></div>;
}
function Sidebar({ page, setPage }) {
  const links = [["dashboard", "Dashboard", "▦"], ["applications", "Applications", "▤"], ["new", "New Application", "+"], ["policies", "Policy Knowledge Base", "⌕"]];
  return <aside className="fixed inset-y-0 left-0 z-10 hidden w-64 bg-[#0c2342] text-white md:block"><div className="flex h-20 items-center border-b border-white/10 px-7"><div className="mr-3 grid h-9 w-9 place-items-center rounded-lg bg-blue-500 font-bold">M</div><div><div className="font-bold tracking-wide">Mortgage<span className="text-blue-300">AI</span></div><div className="text-[10px] uppercase tracking-widest text-slate-400">Processing system</div></div></div><nav className="space-y-2 p-4">{links.map(([key, label, icon]) => <button key={key} onClick={() => setPage(key)} className={`flex w-full items-center gap-3 rounded-lg px-4 py-3 text-left text-sm ${page === key || (key === "applications" && page === "details") ? "bg-blue-500/20 font-semibold text-blue-200" : "text-slate-300 hover:bg-white/5"}`}><span className="w-5 text-center text-lg">{icon}</span>{label}</button>)}</nav><div className="absolute bottom-6 left-6 right-6 rounded-xl border border-white/10 bg-white/5 p-4 text-xs text-slate-400"><div className="mb-1 font-semibold text-slate-200">Phase 4</div>AI-assisted document and financial review requires human verification.</div></aside>;
}
function Header({ title, setPage }) { return <header className="mb-8 flex items-center justify-between"><div><h1 className="text-2xl font-bold text-slate-900">{title}</h1><p className="mt-1 text-sm text-slate-500">Manage your mortgage pipeline with confidence.</p></div><button onClick={() => setPage("new")} className="primary-button hidden sm:block">+ New application</button></header>; }
function ApplicationTable({ applications, onOpen, compact = false }) {
  if (!applications.length) return <div className="py-14 text-center text-sm text-slate-500">No applications found.</div>;
  return <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-5 py-3">Application ID</th><th className="px-5 py-3">Borrower</th><th className="px-5 py-3">Loan amount</th><th className="px-5 py-3">Date created</th><th className="px-5 py-3">Status</th><th /></tr></thead><tbody className="divide-y divide-slate-100">{applications.slice(0, compact ? 5 : undefined).map((app) => <tr key={app.id} className="hover:bg-slate-50"><td className="whitespace-nowrap px-5 py-4 font-semibold text-blue-700">{app.id}</td><td className="whitespace-nowrap px-5 py-4 font-medium">{app.borrower_name}</td><td className="whitespace-nowrap px-5 py-4">{formatMoney(app.loan_amount)}</td><td className="whitespace-nowrap px-5 py-4 text-slate-500">{formatDate(app.created_at)}</td><td className="px-5 py-4"><StatusBadge status={app.status} /></td><td className="px-5 py-4 text-right"><button onClick={() => onOpen(app.id)} className="font-semibold text-blue-600 hover:text-blue-800">{compact ? "Open" : "View"}</button></td></tr>)}</tbody></table></div>;
}
function Dashboard({ applications, setPage, onOpen }) {
  const counts = useMemo(() => Object.fromEntries(statuses.map((s) => [s, applications.filter((a) => a.status === s).length])), [applications]);
  const cards = [["Total Applications", applications.length, "text-slate-900"], ["Draft", counts.Draft, "text-slate-700"], ["Processing", counts.Processing, "text-blue-600"], ["Needs Review", counts["Needs Review"], "text-amber-600"], ["Completed", counts.Completed, "text-emerald-600"]];
  return <><Header title="Dashboard" setPage={setPage} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">{cards.map(([label, value, color]) => <div key={label} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="text-sm text-slate-500">{label}</div><div className={`mt-2 text-3xl font-bold ${color}`}>{value}</div></div>)}</div><section className="mt-8 rounded-xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h2 className="font-bold">Recent applications</h2><p className="mt-1 text-xs text-slate-500">Your latest mortgage applications</p></div><button onClick={() => setPage("applications")} className="text-sm font-semibold text-blue-600">View all</button></div><ApplicationTable applications={applications} compact onOpen={onOpen} /></section></>;
}
function Form({ initial = emptyForm, onSubmit, saving, submitLabel = "Save application", onCancel, reviewFields = {} }) {
  const [form, setForm] = useState({ ...emptyForm, ...initial }); const [error, setError] = useState("");
  const change = (event) => setForm({ ...form, [event.target.name]: event.target.value });
  const submit = async (event) => {
    event.preventDefault(); setError("");
    const required = ["borrower_name", "monthly_income", "monthly_debt", "loan_amount", "property_value"];
    if (required.some((key) => !String(form[key]).trim())) return setError("Please complete all required fields.");
    if (Number(form.monthly_income) <= 0 || Number(form.property_value) <= 0 || [form.monthly_debt, form.loan_amount].some((v) => Number(v) < 0)) return setError("Income and property value must be greater than zero. Financial values cannot be negative.");
    try { await onSubmit({ ...form, monthly_income: Number(form.monthly_income), monthly_debt: Number(form.monthly_debt), loan_amount: Number(form.loan_amount), property_value: Number(form.property_value), email: form.email || null, phone: form.phone || null, property_address: form.property_address || null, employment_type: form.employment_type || null }); } catch (err) { setError(err.response?.data?.detail || "Unable to save application."); }
  };
  const fields = [["borrower_name", "Borrower full name", "text", true], ["email", "Email address", "email"], ["phone", "Phone number", "tel"], ["monthly_income", "Monthly gross income", "number", true], ["monthly_debt", "Existing monthly debt", "number", true], ["loan_amount", "Requested loan amount", "number", true], ["property_value", "Property value", "number", true], ["property_address", "Property address", "text"]];
  return <form onSubmit={submit} className="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div className="grid gap-5 md:grid-cols-2">{fields.map(([name, label, type, required]) => <label key={name} className={name === "property_address" ? "md:col-span-2" : ""}><span className="label">{label}{required && <span className="text-red-500"> *</span>}</span><input className={`field ${reviewFields[name] ? "border-amber-400 bg-amber-50/40" : ""}`} name={name} type={type} min={type === "number" ? "0" : undefined} step={type === "number" ? "0.01" : undefined} value={form[name] || ""} onChange={change} required={required} />{reviewFields[name] && <span className="mt-1 block text-xs text-amber-700">{reviewFields[name]}</span>}</label>)}<label><span className="label">Employment type</span><select className={`field ${reviewFields.employment_type ? "border-amber-400 bg-amber-50/40" : ""}`} name="employment_type" value={form.employment_type || ""} onChange={change}><option value="">Select employment type</option><option>Salaried</option><option>Self-employed</option><option>Other</option></select>{reviewFields.employment_type && <span className="mt-1 block text-xs text-amber-700">{reviewFields.employment_type}</span>}</label></div>{error && <div className="mt-5 rounded-lg bg-red-50 p-3 text-sm text-red-700">{error}</div>}<div className="mt-7 flex justify-end gap-3"><button type="button" onClick={onCancel} className="secondary-button">Cancel</button><button disabled={saving} className="primary-button">{saving ? "Saving..." : submitLabel}</button></div></form>;
}

const intakeFieldNames = ["borrower_name", "email", "phone", "monthly_income", "monthly_debt", "loan_amount", "property_value", "property_address", "employment_type"];
const intakeLabels = { borrower_name: "Borrower full name", email: "Email address", phone: "Phone number", monthly_income: "Monthly gross income", monthly_debt: "Existing monthly debt", loan_amount: "Requested loan amount", property_value: "Property value", property_address: "Property address", employment_type: "Employment type" };
function IntakeReview({ intake }) {
  if (!intake) return null;
  const warnings = [...(intake.missing_information || []).map((item) => `Missing: ${item}`), ...(intake.uncertain_information || []).map((item) => `Uncertain: ${item}`), ...(intake.conflicting_information || []).map((item) => `Conflict: ${item}`)];
  return <div className="mb-5 rounded-xl border border-blue-200 bg-blue-50/50 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold text-slate-900">Review extracted application</h2><p className="mt-1 text-sm text-slate-600">Source: {intake.original_filename}</p></div><span className="rounded-full bg-amber-100 px-3 py-1 text-xs font-semibold text-amber-800">Verify every value</span></div>{intake.summary && <p className="mt-3 text-sm text-slate-700">{intake.summary}</p>}<div className="mt-4 grid gap-3 md:grid-cols-2">{intakeFieldNames.map((name) => { const field = intake.fields?.[name]; const value = field?.value; return <div key={name} className={`rounded-lg border p-3 ${value === null || value === undefined || value === "" ? "border-amber-200 bg-amber-50" : "border-blue-100 bg-white"}`}><div className="text-xs font-semibold uppercase tracking-wide text-slate-400">{intakeLabels[name]}</div><div className="mt-1 text-sm font-medium text-slate-800">{value === null || value === undefined || value === "" ? "Missing" : String(value)}</div>{field?.source && <div className="mt-1 text-xs text-slate-500">Page {field.source.page || "unavailable"}{field.source.snippet ? ` · ${field.source.snippet}` : ""}</div>}{field?.note && <div className="mt-1 text-xs text-amber-700">Explanation: {field.note}</div>}</div>; })}</div>{warnings.length > 0 && <div className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800"><strong>Review warnings:</strong><ul className="mt-1 list-disc pl-5">{warnings.map((item) => <li key={item}>{item}</li>)}</ul></div>}</div>;
}
function CreateApplication({ onCreate, onCancel, setError }) {
  const [mode, setMode] = useState("manual"); const [intake, setIntake] = useState(null); const [busy, setBusy] = useState(false);
  const upload = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; try { setBusy(true); setError(""); const response = await intakeApplication(file); setIntake(response.data); setMode("upload"); } catch (err) { setError(err.response?.data?.detail || "Loan application could not be processed."); } finally { setBusy(false); } };
  const initial = Object.fromEntries(intakeFieldNames.map((name) => [name, intake?.fields?.[name]?.value ?? ""]));
  const reviewFields = Object.fromEntries(intakeFieldNames.filter((name) => intake?.fields?.[name]?.value === null || intake?.fields?.[name]?.value === undefined || intake?.fields?.[name]?.note).map((name) => [name, intake?.fields?.[name]?.note || "Confirm this extracted value."]));
  return <><div className="mb-5 rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="font-bold">How would you like to start?</h2><div className="mt-4 grid gap-3 sm:grid-cols-2"><button type="button" onClick={() => { setMode("manual"); setIntake(null); }} className={`rounded-lg border p-4 text-left ${mode === "manual" ? "border-blue-500 bg-blue-50" : "border-slate-200"}`}><div className="font-semibold">Manual Entry</div><div className="mt-1 text-sm text-slate-500">Complete the mortgage application form yourself.</div></button><label className={`cursor-pointer rounded-lg border p-4 text-left ${mode === "upload" ? "border-blue-500 bg-blue-50" : "border-slate-200"}`}><div className="font-semibold">Upload Loan Application</div><div className="mt-1 text-sm text-slate-500">Use a PDF or image to pre-fill the form with cited evidence.</div><input className="hidden" type="file" accept=".pdf,.png,.jpg,.jpeg" onChange={upload} disabled={busy} /></label></div>{busy && <p className="mt-3 text-sm text-blue-700">Extracting text and identifying fields...</p>}</div>{intake && <IntakeReview intake={intake} />}<Form key={intake?.intake_id || "manual"} initial={intake ? initial : emptyForm} reviewFields={intake ? reviewFields : {}} onSubmit={(data) => onCreate({ ...data, intake_id: intake?.intake_id || null })} onCancel={onCancel} submitLabel="Create application" /> </>;
}

function FieldList({ fields }) {
  return <div className="space-y-3">{Object.entries(fields || {}).map(([key, field]) => <div key={key} className="rounded-lg border border-slate-100 bg-white p-3"><div className="text-xs font-semibold uppercase tracking-wide text-slate-400">{key.replaceAll("_", " ")}</div><div className="mt-1 text-sm text-slate-700">{field?.value === null || field?.value === undefined ? "Unknown" : typeof field.value === "object" ? JSON.stringify(field.value) : String(field.value)}</div>{field?.source && <div className="mt-1 text-xs text-slate-500">Source: {field.source.document_id || "document"}{field.source.page ? `, page ${field.source.page}` : ""}{field.source.snippet ? ` — ${field.source.snippet}` : ""}</div>}</div>)}</div>;
}
function AnalysisPanel({ analysis, title = "Nemotron document analysis" }) {
  if (!analysis) return null;
  return <div className="mt-4 rounded-lg border border-indigo-100 bg-indigo-50/40 p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">{title}</h3><StatusBadge status={analysis.status} /></div><div className="mt-2 text-xs font-semibold text-indigo-700">AI-generated — verify against original documents</div>{analysis.summary && <p className="mt-3 text-sm leading-6 text-slate-700">{analysis.summary}</p>}{analysis.structured_fields && <><h4 className="mt-4 mb-2 text-sm font-bold">Structured fields</h4><FieldList fields={analysis.structured_fields} /></>}{analysis.borrower_details && <><h4 className="mt-4 mb-2 text-sm font-bold">Borrower details</h4><FieldList fields={analysis.borrower_details} /><h4 className="mt-4 mb-2 text-sm font-bold">Income information</h4><FieldList fields={analysis.income_information} /></>}{[["Missing or unclear information", analysis.missing_information], ["Review flags", analysis.review_flags], ["Conflicting values", analysis.conflicting_values]].map(([label, items]) => items?.length ? <div key={label} className="mt-4"><h4 className="text-sm font-bold">{label}</h4><ul className="mt-1 list-disc pl-5 text-sm text-slate-700">{items.map((item) => <li key={item}>{item}</li>)}</ul></div> : null)}{analysis.source_document_ids?.length > 0 && <div className="mt-4 text-xs text-slate-600">Source documents: {analysis.source_document_ids.join(", ")}</div>}{analysis.input_truncated && <p className="mt-4 text-xs text-amber-700">The extracted text exceeded the model input limit; only the first {analysis.input_characters} characters were analyzed.</p>}{analysis.error_message && <p className="mt-3 text-sm text-red-700">{analysis.error_message}</p>}</div>;
}

function DocumentManager({ applicationId, flash, setError }) {
  const [documents, setDocuments] = useState([]); const [loading, setLoading] = useState(true); const [category, setCategory] = useState("Other"); const [uploading, setUploading] = useState(false); const [progress, setProgress] = useState(0); const [selected, setSelected] = useState(null); const [analysis, setAnalysis] = useState(null); const [busyId, setBusyId] = useState(null);
  const load = async () => { try { setLoading(true); const response = await getDocuments(applicationId); const enriched = await Promise.all(response.data.map(async (document) => { if (document.extraction_status !== "Extracted") return document; try { const result = await getDocumentAnalysis(applicationId, document.id); return { ...document, analysis_status: result.data.status }; } catch { return document; } })); setDocuments(enriched); } catch (err) { setError(err.response?.data?.detail || "Documents could not be loaded."); } finally { setLoading(false); } };
  useEffect(() => { load(); }, [applicationId]);
  const upload = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; try { setUploading(true); setProgress(0); await uploadDocument(applicationId, file, category, (event) => setProgress(Math.round((event.loaded * 100) / (event.total || file.size)))); await load(); flash("Document uploaded."); } catch (err) { setError(err.response?.data?.detail || "Document upload failed."); } finally { setUploading(false); } };
  const extract = async (document) => { try { setBusyId(document.id); const response = await extractDocument(applicationId, document.id); setDocuments((items) => items.map((item) => item.id === document.id ? response.data : item)); flash("Text extraction completed."); } catch (err) { setError(err.response?.data?.detail || "Text extraction failed."); await load(); } finally { setBusyId(null); } };
  const runAnalysis = async (document) => { try { setBusyId(document.id); const response = await analyzeDocument(applicationId, document.id); setAnalysis(response.data); setSelected(document); setDocuments((items) => items.map((item) => item.id === document.id ? { ...item, analysis_status: response.data.status } : item)); flash("Nemotron analysis completed."); } catch (err) { setError(err.response?.data?.detail || "Nemotron analysis failed."); } finally { setBusyId(null); } };
  const viewAnalysis = async (document) => { try { setBusyId(document.id); const response = await getDocumentAnalysis(applicationId, document.id); setAnalysis(response.data); setSelected(document); } catch (err) { setError(err.response?.data?.detail || "Analysis could not be loaded."); } finally { setBusyId(null); } };
  const remove = async (document) => { if (!window.confirm(`Delete ${document.original_filename}?`)) return; try { await deleteDocument(applicationId, document.id); if (selected?.id === document.id) { setSelected(null); setAnalysis(null); } await load(); flash("Document deleted."); } catch (err) { setError(err.response?.data?.detail || "Document could not be deleted."); } };
  const changeCategory = async (document, value) => { try { const response = await updateDocumentCategory(applicationId, document.id, value); setDocuments((items) => items.map((item) => item.id === document.id ? response.data : item)); } catch (err) { setError(err.response?.data?.detail || "Category could not be updated."); } };
  const viewText = async (document) => { try { setBusyId(document.id); const response = await getDocumentText(applicationId, document.id); setSelected({ ...document, ...response.data }); } catch (err) { setError(err.response?.data?.detail || "Extracted text could not be loaded."); } finally { setBusyId(null); } };
  return <section className="mt-6 rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-4"><div><h2 className="font-bold">Documents</h2><p className="mt-1 text-sm text-slate-500">Upload, extract, and analyze sensitive borrower documents.</p></div><div className="flex items-center gap-2"><select className="rounded-lg border border-slate-200 px-3 py-2 text-sm" value={category} onChange={(e) => setCategory(e.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select><label className="primary-button cursor-pointer">{uploading ? `Uploading ${progress}%` : "Choose file"}<input className="hidden" type="file" accept=".pdf,.png,.jpg,.jpeg" onChange={upload} disabled={uploading} /></label></div></div>{uploading && <div className="mt-4 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full bg-blue-600 transition-all" style={{ width: `${progress}%` }} /></div>}{loading ? <Loading /> : !documents.length ? <div className="mt-6 rounded-lg border border-dashed border-slate-300 py-10 text-center text-sm text-slate-500">No documents uploaded yet.</div> : <div className="mt-5 divide-y divide-slate-100">{documents.map((document) => <div key={document.id} className="py-4"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="min-w-0"><div className="truncate font-semibold text-slate-800">{document.original_filename}</div><div className="mt-1 text-xs text-slate-500">{document.content_type} · {formatSize(document.file_size)} · {formatDate(document.uploaded_at)}</div></div><div className="flex flex-wrap items-center gap-2"><select className="rounded-lg border border-slate-200 px-2 py-1.5 text-xs" value={document.category} onChange={(e) => changeCategory(document, e.target.value)}>{categories.map((item) => <option key={item}>{item}</option>)}</select><StatusBadge status={document.extraction_status} />{document.extraction_status === "Extracted" && <><button onClick={() => viewText(document)} className="secondary-button px-3 py-1.5 text-xs">View text</button><button onClick={() => runAnalysis(document)} disabled={busyId === document.id} className="primary-button px-3 py-1.5 text-xs">{busyId === document.id ? "Analyzing..." : "Analyze with Nemotron"}</button>{document.analysis_status === "Completed" && <button onClick={() => viewAnalysis(document)} className="secondary-button px-3 py-1.5 text-xs">View AI result</button>}</>}{document.extraction_status !== "Extracted" && <button onClick={() => extract(document)} disabled={busyId === document.id} className="secondary-button px-3 py-1.5 text-xs">Extract text</button>}<button onClick={() => remove(document)} className="px-2 py-1.5 text-xs font-semibold text-red-600">Delete</button></div></div>{document.extraction_status === "Failed" && <div className="mt-2 text-xs text-red-600">{document.extraction_error}</div>}{analysis && selected?.id === document.id && <AnalysisPanel analysis={analysis} />}{selected?.id === document.id && selected?.extracted_text && <div className="mt-4 rounded-lg border border-blue-100 bg-blue-50/40 p-4"><div className="flex items-center justify-between gap-2"><h3 className="font-bold">Extracted text</h3><button onClick={() => navigator.clipboard.writeText(selected.extracted_text).then(() => flash("Text copied to clipboard."))} className="secondary-button px-3 py-1.5 text-xs">Copy text</button></div><p className="mt-2 text-xs text-amber-700">OCR/text extraction may contain mistakes. Check this content against the original document.</p><pre className="mt-4 max-h-96 overflow-auto whitespace-pre-wrap rounded-lg bg-white p-4 text-sm leading-6 text-slate-700">{selected.extracted_text}</pre></div>}</div>)}</div>}</section>;
}

function FinancialAnalysis({ applicationId, flash, setError }) {
  const [validation, setValidation] = useState(null);
  const [busy, setBusy] = useState(false);
  const load = async () => {
    try {
      const response = await getValidation(applicationId);
      setValidation(response.data);
    } catch (err) {
      if (err.response?.status !== 404) setError(err.response?.data?.detail || "Financial validation could not be loaded.");
    }
  };
  useEffect(() => { load(); }, [applicationId]);
  const run = async (recalculate = false) => {
    try {
      setBusy(true);
      const response = recalculate
        ? await recalculateValidation(applicationId)
        : await validateApplication(applicationId);
      setValidation(response.data);
      flash("Financial validation completed.");
    } catch (err) {
      setError(err.response?.data?.detail || "Financial validation failed.");
    } finally {
      setBusy(false);
    }
  };
  const cards = validation ? [
    ["DTI", validation.dti === null ? "—" : `${validation.dti.toFixed(2)}%`],
    ["LTV", validation.ltv === null ? "—" : `${validation.ltv.toFixed(2)}%`],
    ["Monthly income", formatMoney(validation.monthly_income)],
    ["Monthly debt", formatMoney(validation.monthly_debt)],
    ["Loan amount", formatMoney(validation.loan_amount)],
    ["Property value", formatMoney(validation.property_value)],
  ] : [];
  return <section className="mt-6 rounded-xl border border-slate-200 bg-white p-6 shadow-sm">
    <div className="flex flex-wrap items-start justify-between gap-3">
      <div><h2 className="font-bold">Financial analysis</h2><p className="mt-1 text-sm text-slate-500">Deterministic calculations and document comparisons. This is not an approval decision.</p></div>
      <button onClick={() => run(Boolean(validation))} disabled={busy} className="primary-button">{busy ? "Validating..." : validation ? "Recalculate validation" : "Run financial validation"}</button>
    </div>
    {!validation ? <div className="mt-6 rounded-lg border border-dashed border-slate-300 py-8 text-center text-sm text-slate-500">Run validation to calculate DTI/LTV and compare application data with analyzed documents.</div> : <>
      <div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{cards.map(([label, value]) => <div key={label} className="rounded-lg border border-slate-100 bg-slate-50 p-4"><div className="text-xs uppercase tracking-wide text-slate-400">{label}</div><div className="mt-1 text-xl font-bold text-slate-800">{value}</div></div>)}</div>
      <div className="mt-5 flex flex-wrap items-center gap-3"><StatusBadge status={validation.validation_status} /><span className="text-sm text-slate-600">Income consistency: <strong>{validation.income_consistency}</strong></span><span className="text-sm text-slate-600">Document consistency: <strong>{validation.document_consistency}</strong></span></div>
      <div className="mt-4 rounded-lg border border-amber-100 bg-amber-50 p-3 text-sm text-amber-800">AI-assisted financial review — human verification required. Tolerance and policy thresholds are software review settings, not lending-policy or regulatory decisions.</div>
      {validation.missing_information?.length > 0 && <div className="mt-4"><h3 className="font-semibold">Missing information</h3><ul className="mt-1 list-disc pl-5 text-sm text-slate-700">{validation.missing_information.map((item) => <li key={item}>{item}</li>)}</ul></div>}
      {validation.issues?.length > 0 && <div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="border-b border-slate-100 text-xs uppercase tracking-wide text-slate-400"><tr><th className="px-3 py-2">Field</th><th className="px-3 py-2">Application</th><th className="px-3 py-2">Document</th><th className="px-3 py-2">Difference</th><th className="px-3 py-2">Status</th><th className="px-3 py-2">Source</th></tr></thead><tbody className="divide-y divide-slate-100">{validation.issues.map((issue) => <tr key={issue.id}><td className="px-3 py-3 font-medium">{issue.field_name}</td><td className="px-3 py-3">{issue.application_value || "—"}</td><td className="px-3 py-3">{issue.document_value || "—"}</td><td className="px-3 py-3">{issue.difference === null ? "—" : issue.difference}</td><td className="px-3 py-3"><StatusBadge status={issue.severity} /></td><td className="px-3 py-3">{issue.source_document_id ? <button className="font-semibold text-blue-600" onClick={() => setError(`Source document: ${issue.source_document_id}`)}>View source ID</button> : "—"}</td></tr>)}</tbody></table></div>}
      <p className="mt-4 text-xs text-slate-500">Calculated {formatDate(validation.calculated_at)}. No automatic approval or rejection is performed.</p>
    </>}
  </section>;
}

function ApplicationSummary({ applicationId, flash, setError }) {
  const [summary, setSummary] = useState(null); const [busy, setBusy] = useState(false);
  const load = async () => { try { const response = await getApplicationAnalysis(applicationId); setSummary(response.data); } catch (err) { if (err.response?.status !== 404) setError(err.response?.data?.detail || "Application summary could not be loaded."); } };
  useEffect(() => { load(); }, [applicationId]);
  const run = async () => { try { setBusy(true); const response = await analyzeApplication(applicationId); setSummary(response.data); flash("Application summary completed."); } catch (err) { setError(err.response?.data?.detail || "Application summary failed."); } finally { setBusy(false); } };
  return <section className="mt-6 rounded-xl border border-indigo-100 bg-indigo-50/30 p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold">Application AI summary</h2><p className="mt-1 text-sm text-slate-500">Combines successfully analyzed documents only. This is not an eligibility or approval decision.</p></div><button onClick={run} disabled={busy} className="primary-button">{busy ? "Summarizing..." : "Summarize application"}</button></div>{summary && <AnalysisPanel analysis={summary} title="Nemotron application summary" />}</section>;
}

function PolicyAnalysis({ applicationId, flash, setError }) {
  const [analysis, setAnalysis] = useState(null); const [busy, setBusy] = useState(false);
  const run = async () => { try { setBusy(true); const response = await analyzeApplicationPolicy(applicationId); setAnalysis(response.data); flash("Policy analysis completed."); } catch (err) { setError(err.response?.data?.detail || "Policy analysis failed."); } finally { setBusy(false); } };
  return <section className="mt-6 rounded-xl border border-cyan-100 bg-cyan-50/30 p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold">Policy analysis</h2><p className="mt-1 text-sm text-slate-500">Retrieves active demonstration policies before asking Nemotron for an explanation.</p></div><button onClick={run} disabled={busy} className="primary-button">{busy ? "Analyzing..." : "Analyze against policy"}</button></div>{analysis && <div className="mt-4"><div className="text-xs font-semibold text-cyan-800">AI-assisted policy analysis — human decision required.</div><p className="mt-3 text-sm leading-6 text-slate-700">{analysis.explanation}</p>{analysis.policy_findings?.length > 0 && <ul className="mt-3 list-disc pl-5 text-sm text-slate-700">{analysis.policy_findings.map((item) => <li key={item}>{item}</li>)}</ul>}<div className="mt-4 grid gap-3 sm:grid-cols-2">{analysis.citations?.map((citation) => <div key={citation.chunk_id} className="rounded-lg border border-cyan-100 bg-white p-3 text-sm"><div className="font-semibold">{citation.section || "Policy section"}</div><div className="text-xs text-slate-500">Page {citation.page_number || "unavailable"} · Similarity {citation.similarity ?? "—"}</div><p className="mt-2 text-slate-700">{citation.text}</p></div>)}</div>{analysis.citations?.length === 0 && <p className="mt-3 text-sm text-amber-700">No relevant policy evidence was found.</p>}</div>}</section>;
}

function UnderwritingAssistant({ applicationId, flash, setError }) {
  const [report, setReport] = useState(null); const [events, setEvents] = useState([]); const [busy, setBusy] = useState(false);
  const run = async () => { try { setBusy(true); const response = await runUnderwriting(applicationId); setReport((await getUnderwritingReport(applicationId)).data); setEvents((await getUnderwritingEvents(applicationId)).data); flash(response.data.status === "COMPLETED" ? "Underwriting review completed." : "Underwriting review needs attention."); } catch (err) { setError(err.response?.data?.detail || "Underwriting review failed."); } finally { setBusy(false); } };
  return <section className="mt-6 rounded-xl border border-violet-100 bg-violet-50/30 p-6 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="font-bold">AI Underwriting Assistant</h2><p className="mt-1 text-sm text-slate-500">Coordinates document processing, financial validation, policy retrieval, and evidence review.</p></div><button onClick={run} disabled={busy} className="primary-button">{busy ? "Analyzing application..." : "Run AI underwriting review"}</button></div>{events.length > 0 && <div className="mt-4 space-y-2">{events.map((event) => <div key={event.id} className="flex gap-2 text-sm"><span className={event.status === "failed" ? "text-red-600" : "text-emerald-600"}>{event.status === "failed" ? "⚠" : "✓"}</span><span>{event.short_result}</span></div>)}</div>}{report && <div className="mt-5 rounded-lg border border-violet-100 bg-white p-4"><div className="flex items-center justify-between"><h3 className="font-bold">Underwriting review report</h3><StatusBadge status={report.status} /></div><p className="mt-3 text-sm leading-6 text-slate-700">{report.summary}</p><div className="mt-3 grid gap-3 sm:grid-cols-3"><div><div className="text-xs text-slate-500">Documents processed</div><div className="font-bold">{report.documents_processed}</div></div><div><div className="text-xs text-slate-500">DTI</div><div className="font-bold">{report.financial_metrics?.dti ?? "—"}%</div></div><div><div className="text-xs text-slate-500">LTV</div><div className="font-bold">{report.financial_metrics?.ltv ?? "—"}%</div></div></div>{report.missing_information?.length > 0 && <div className="mt-4"><h4 className="font-semibold">Missing information</h4><ul className="list-disc pl-5 text-sm">{report.missing_information.map((item) => <li key={item}>{item}</li>)}</ul></div>}{report.policy_findings?.length > 0 && <div className="mt-4"><h4 className="font-semibold">Policy evidence</h4>{report.policy_findings.map((item, index) => <div key={`${item.source}-${index}`} className="mt-2 rounded border border-slate-100 p-3 text-sm"><div className="font-semibold">{item.title}</div><div className="text-xs text-slate-500">{item.source} · v{item.version || "—"} · Page {item.page || "unavailable"}</div><p className="mt-1">{item.text}</p></div>)}</div>}<p className="mt-4 text-xs font-semibold text-violet-700">{report.warning}</p></div>}</section>;
}

function Policies({ flash, setError }) {
  const [policies, setPolicies] = useState([]); const [results, setResults] = useState([]); const [query, setQuery] = useState(""); const [file, setFile] = useState(null); const [form, setForm] = useState({ title: "", category: "General", version: "2026.1", effective_date: "" }); const [busy, setBusy] = useState(false);
  const load = async () => { try { const response = await getPolicies(); setPolicies(response.data); } catch (err) { setError(err.response?.data?.detail || "Policies could not be loaded."); } };
  useEffect(() => { load(); }, []);
  const upload = async (event) => { event.preventDefault(); if (!file) return setError("Choose a PDF or TXT policy file."); try { setBusy(true); await uploadPolicy(file, form); setFile(null); await load(); flash("Policy indexed successfully."); } catch (err) { setError(err.response?.data?.detail || "Policy upload failed."); } finally { setBusy(false); } };
  const search = async (event) => { event.preventDefault(); if (!query.trim()) return; try { const response = await searchPolicies(query); setResults(response.data.results); } catch (err) { setError(err.response?.data?.detail || "Policy search failed."); } };
  const remove = async (id) => { try { await deletePolicy(id); await load(); flash("Policy removed."); } catch (err) { setError(err.response?.data?.detail || "Policy deletion failed."); } };
  return <><Header title="Policy Knowledge Base" setPage={() => {}} /><div className="mb-5 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800"><strong>Sample / Demonstration Policy.</strong> Do not treat uploaded sample policies as actual laws, lender rules, or regulatory advice.</div><div className="grid gap-6 lg:grid-cols-2"><form onSubmit={upload} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="font-bold">Add policy document</h2><input className="field" placeholder="Policy title" required value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} /><input className="field" placeholder="Category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /><input className="field" placeholder="Version" required value={form.version} onChange={(e) => setForm({ ...form, version: e.target.value })} /><input className="field" type="date" value={form.effective_date} onChange={(e) => setForm({ ...form, effective_date: e.target.value })} /><input className="field" type="file" accept=".pdf,.txt" required onChange={(e) => setFile(e.target.files[0])} /><button className="primary-button" disabled={busy}>{busy ? "Indexing..." : "Upload and index policy"}</button></form><div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="font-bold">Ask the policy index</h2><form onSubmit={search} className="mt-3 flex gap-2"><input className="field mt-0" placeholder="What is the DTI requirement?" value={query} onChange={(e) => setQuery(e.target.value)} /><button className="primary-button">Search</button></form><div className="mt-4 space-y-3">{results.map((item) => <div key={item.chunk_id} className="rounded-lg border border-slate-100 p-3 text-sm"><div className="font-semibold">{item.section || "Policy section"}</div><div className="text-xs text-slate-500">Page {item.page_number || "unavailable"} · Relevance {item.similarity}</div><p className="mt-1 text-slate-700">{item.text}</p></div>)}</div></div></div><section className="mt-6 rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="font-bold">Indexed policies</h2>{policies.length === 0 ? <p className="mt-3 text-sm text-slate-500">No policies indexed yet.</p> : <div className="mt-3 space-y-2">{policies.map((policy) => <div key={policy.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-slate-100 p-3 text-sm"><div><div className="font-semibold">{policy.title}</div><div className="text-xs text-slate-500">{policy.category} · v{policy.version} · {policy.effective_date || "Effective date unavailable"} · {policy.status}</div></div><button className="text-sm font-semibold text-red-600" onClick={() => remove(policy.id)}>Delete</button></div>)}</div>}</section></>;
}

function Applications({ applications, onOpen, setPage }) { const [search, setSearch] = useState(""); const [filter, setFilter] = useState(""); const filtered = applications.filter((a) => (!filter || a.status === filter) && `${a.id} ${a.borrower_name}`.toLowerCase().includes(search.toLowerCase())); return <><Header title="Applications" setPage={setPage} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><input className="field mt-0 sm:max-w-sm" placeholder="Search borrower or application ID..." value={search} onChange={(e) => setSearch(e.target.value)} /><select className="field mt-0 sm:max-w-xs" value={filter} onChange={(e) => setFilter(e.target.value)}><option value="">All statuses</option>{statuses.map((s) => <option key={s}>{s}</option>)}</select></div><section className="rounded-xl border border-slate-200 bg-white shadow-sm"><ApplicationTable applications={filtered} onOpen={onOpen} /></section></>; }
function Details({ application, onSubmit, onStatus, onCancel, setPage, loading, flash, setError }) {
  if (loading || !application) return <><Header title="Application details" setPage={setPage} /><Loading /></>;
  return <><Header title={application.borrower_name} setPage={setPage} /><div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div><div className="text-xs uppercase tracking-wide text-slate-400">Application ID</div><div className="mt-1 font-bold text-blue-700">{application.id}</div><div className="mt-1 text-sm text-slate-500">Created {formatDate(application.created_at)}</div></div><div className="flex items-center gap-3"><StatusBadge status={application.status} /><select className="rounded-lg border border-slate-200 px-3 py-2 text-sm" value={application.status} onChange={(e) => onStatus(e.target.value)}>{statuses.map((s) => <option key={s}>{s}</option>)}</select></div></div><Form initial={application} onSubmit={onSubmit} onCancel={onCancel} submitLabel="Save changes" /><DocumentManager applicationId={application.id} flash={flash} setError={setError} /><ApplicationSummary applicationId={application.id} flash={flash} setError={setError} /><FinancialAnalysis applicationId={application.id} flash={flash} setError={setError} /><PolicyAnalysis applicationId={application.id} flash={flash} setError={setError} /><UnderwritingAssistant applicationId={application.id} flash={flash} setError={setError} /></>;
}
function AuthenticatedApp() {
  const [page, setPage] = useState("dashboard"); const [applications, setApplications] = useState([]); const [selectedId, setSelectedId] = useState(null); const [selected, setSelected] = useState(null); const [loading, setLoading] = useState(true); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const signOut = async () => { try { await logout(); } catch { /* local token removal is still required */ } finally { localStorage.removeItem("mortgage_access_token"); window.location.reload(); } };
  const load = async () => { try { setLoading(true); const response = await getApplications(); setApplications(response.data); setError(""); } catch { setError("Could not connect to the API. Start the FastAPI server and refresh."); } finally { setLoading(false); } };
  useEffect(() => { load(); }, []);
  const open = async (id) => { try { setLoading(true); const response = await getApplication(id); setSelected(response.data); setSelectedId(id); setPage("details"); } catch { setError("Application could not be loaded."); } finally { setLoading(false); } };
  const flash = (text) => { setMessage(text); window.setTimeout(() => setMessage(""), 3000); };
  const create = async (data) => { const response = await createApplication(data); await load(); flash(`Application ${response.data.id} created.`); setPage("applications"); };
  const update = async (data) => { const response = await updateApplication(selectedId, { ...data, status: selected.status }); setSelected(response.data); await load(); flash("Application details updated."); };
  const statusChange = async (value) => { try { const response = await updateStatus(selectedId, value); setSelected(response.data); await load(); flash("Status updated."); } catch (err) { setError(err.response?.data?.detail || "Status update failed."); } };
  const title = page === "new" ? "New application" : page === "applications" ? "Applications" : page === "details" ? "Application details" : page === "policies" ? "Policy Knowledge Base" : "Dashboard";
  return <div><Sidebar page={page} setPage={setPage} /><main className="min-h-screen md:ml-64"><div className="mx-auto max-w-7xl p-5 sm:p-8"><div className="mb-4 flex justify-end"><button onClick={signOut} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-50">Sign out</button></div><div className="mb-5 flex gap-2 overflow-x-auto md:hidden">{["dashboard", "applications", "new", "policies"].map((p) => <button key={p} onClick={() => setPage(p)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-sm font-semibold ${page === p ? "bg-blue-600 text-white" : "bg-white text-slate-600"}`}>{p === "new" ? "New application" : p === "policies" ? "Policies" : p[0].toUpperCase() + p.slice(1)}</button>)}</div>{message && <div className="mb-5 rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700">{message}</div>}{error && <div className="mb-5 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div>}{loading && page !== "new" && page !== "details" && page !== "policies" ? <><Header title={title} setPage={setPage} /><Loading /></> : page === "dashboard" ? <Dashboard applications={applications} setPage={setPage} onOpen={open} /> : page === "new" ? <><Header title={title} setPage={setPage} /><CreateApplication onCreate={create} onCancel={() => setPage("dashboard")} setError={setError} /></> : page === "applications" ? <Applications applications={applications} onOpen={open} setPage={setPage} /> : page === "policies" ? <Policies flash={flash} setError={setError} /> : <Details application={selected} onSubmit={update} onStatus={statusChange} onCancel={() => setPage("applications")} setPage={setPage} loading={loading} flash={flash} setError={setError} />}</div></main></div>;
}
function App() {
  const [user, setUser] = useState(null); const [authLoading, setAuthLoading] = useState(true);
  useEffect(() => { const expire = () => setUser(null); window.addEventListener("mortgage-auth-expired", expire); return () => window.removeEventListener("mortgage-auth-expired", expire); }, []);
  useEffect(() => { if (!localStorage.getItem("mortgage_access_token")) return setAuthLoading(false); getMe().then((response) => setUser(response.data)).catch(() => localStorage.removeItem("mortgage_access_token")).finally(() => setAuthLoading(false)); }, []);
  if (authLoading) return <Loading />;
  if (!user) return <Login onLogin={setUser} />;
  return <AuthenticatedApp />;
}
export default App;
